
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_pw91_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_pw91", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.322469480171118e+00, -4.240715940357124e+00, -4.126246752078114e+00, -3.967860068312586e+00, -3.752415411856092e+00, -3.466454068846867e+00, -3.099972051016899e+00, -2.653077927374716e+00, -2.144330552510053e+00, -1.612185034553762e+00, -1.090152522731953e+00, -7.115716628500232e-01, -6.041766795250194e-01, -5.038376969930504e-01, -3.717083361475274e-01, -2.433283501771075e-01, -1.321778237517229e-01, -2.336700869424606e-02, -2.464746861827491e-04, -3.290622924029963e-07]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


